"""
Kaggle GPU job: score the saved corpus WAVs with one judge (torch/score_judge.py), no regeneration.

Input: the output of kernel samlinlinlin/musicgen-prune-corpus (kernel_sources), i.e.
corpus/<id>.json + wavs.tar. Do not re-push that kernel: a new version replaces those outputs.

JUDGE = "mulan": MuQ-MuLan; `pip install muq` + transformers 4.57.3 in the main env
                 (this job never runs generation, so it does not need transformers 5.17).
JUDGE = "cmi":   CMI-RM in its own venv (--system-site-packages, shares Kaggle's torch) with
                 transformers 4.57.3 + CMI-RewardBench's extras. kaggle_cmi/run.py is this
                 file with JUDGE = "cmi" (written by kaggle_job/bundle.py).

  python kaggle_job/bundle.py kaggle_judge kaggle_cmi && uvx kaggle kernels push -p kaggle_judge
Outputs in /kaggle/working: judge_<JUDGE>.json ({id: {key: [8 floats]}}), env*.txt,
score.log, summary.json.
"""
import json, subprocess, sys, time
from pathlib import Path

JUDGE = "cmi"
OUT = Path("/kaggle/working") if Path("/kaggle/working").exists() else Path.cwd()
SRC = OUT / "src"
WAVS = Path("/tmp/wavs")
CMI = Path("/tmp/CMI-RewardBench")    # not under /kaggle/working: kept out of the outputs
VENV = Path("/tmp/cmienv")
PY = sys.executable
TORCH_V = "import torch, transformers; print(torch.__version__, transformers.__version__)"


def sh(cmd, log=None, cwd=OUT):
    """Run cmd, tee output to OUT/log, return exit code."""
    lines = []
    p = subprocess.Popen(cmd, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    for line in p.stdout:
        print(line, end="", flush=True); lines.append(line)
    rc = p.wait()
    if log:
        (OUT / log).write_text("".join(lines))
    return rc


def main():
    t0, summary = time.time(), {"judge": JUDGE}
    for name, text in SOURCES.items():
        (SRC / name).parent.mkdir(parents=True, exist_ok=True)
        (SRC / name).write_text(text)
    tar = next(Path("/kaggle/input").rglob("wavs.tar"))
    corpus = tar.parent / "corpus"
    summary["input"] = str(tar.parent)
    WAVS.mkdir(parents=True, exist_ok=True)
    sh(["tar", "xf", str(tar), "-C", str(WAVS)])
    summary["n_wavs"] = len(list(WAVS.glob("*.wav")))
    sh([PY, "-c", TORCH_V], "env_before.txt")
    if JUDGE == "mulan":
        py = PY
        summary["setup"] = sh([PY, "-m", "pip", "install", "-q", "muq", "transformers==4.57.3"])
    else:
        py = str(VENV / "bin/python")
        summary["setup"] = (
            sh(["git", "clone", "-q", "--depth", "1", "https://github.com/Haiwen-Xia/CMI-RewardBench", str(CMI)])
            # Kaggle's Python has no ensurepip: make the venv without pip, install with the main pip
            or sh([PY, "-m", "venv", "--system-site-packages", "--without-pip", str(VENV)])
            or sh([PY, "-m", "pip", "--python", py, "install", "-q", "transformers==4.57.3", "einops", "librosa", "nnAudio",
                   "easydict", "x-clip", "omegaconf"])
            or sh([PY, "-c", "from huggingface_hub import snapshot_download as d; "
                   f"print(d('HaiwenXia/CMI-RM', local_dir='{CMI}/baselines/model'))"]))
    sh([py, "-c", TORCH_V], "env_after.txt")
    summary["env_before"] = (OUT / "env_before.txt").read_text().strip()
    summary["env_after"] = (OUT / "env_after.txt").read_text().strip()
    cmd = [py, str(SRC / "torch/score_judge.py"), "score", "--judge", JUDGE, "--corpus", str(corpus),
           "--wavs", str(WAVS), "--out", str(OUT / f"judge_{JUDGE}.json")]
    if JUDGE == "cmi":
        cmd += ["--repo", str(CMI), "--ckpt", str(CMI / "baselines/model/model.safetensors")]
    summary["score_exit"] = sh(cmd, "score.log", cwd=SRC / "torch")
    out = OUT / f"judge_{JUDGE}.json"
    summary["done"] = len(json.loads(out.read_text())) if out.exists() else 0
    summary["minutes"] = round((time.time() - t0) / 60, 1)
    (OUT / "summary.json").write_text(json.dumps(summary, indent=1))
    print(json.dumps(summary, indent=1))
    sys.exit(int(summary["score_exit"] != 0))
# --- bundled sources: generated by kaggle_job/bundle.py, do not edit below ---
SOURCES = {'torch/scorers.py': '"""\nAudio scorers for the corpus. Each takes (wavs (B, samples) float32 numpy at 32 kHz, prompt)\nand returns {score name: (B,) numpy}.\n\n  Clap      pruner: text-audio cosine, chunked 10 s mean (deterministic, see ../bench.py)\n  Audiobox  judge: Audiobox Aesthetics CE/CU/PC/PQ (pip install audiobox_aesthetics)\n  CmiRm     judge: CMI-RM alignment + quality (github.com/Haiwen-Xia/CMI-RewardBench)\n  MuqMulan  judge: MuQ-MuLan text-audio similarity (pip install muq; needs transformers 4.x)\n"""\nimport sys\nimport numpy as np\nimport torch\n\nSR = 32000  # musicgen / EnCodec 32 kHz\n\n\nclass Clap:\n    """laion/clap-htsat-unfused sees 10 s max and its processor RANDOMLY crops longer clips\n    ("rand_trunc"), so: cut each clip into 10 s chunks, embed every chunk, average per clip.\n    Deterministic, and covers the whole clip."""\n    def __init__(self, device="cpu", name="laion/clap-htsat-unfused"):\n        from transformers import ClapModel, ClapProcessor\n        self.dev = device\n        self.model = ClapModel.from_pretrained(name).eval().to(device)\n        self.proc = ClapProcessor.from_pretrained(name)\n\n    @staticmethod\n    def _feat(out):  # transformers 5 may return a ModelOutput instead of a tensor\n        return out if hasattr(out, "norm") else out.pooler_output\n\n    @torch.inference_mode()\n    def __call__(self, wavs, prompt):\n        from scipy.signal import resample_poly\n        t = self._feat(self.model.get_text_features(**self.proc.tokenizer([prompt], return_tensors="pt").to(self.dev)))\n        t = t / t.norm(dim=-1, keepdim=True)\n        W = 480_000                                                   # 10 s at 48 kHz\n        chunks, owner = [], []\n        for b, w in enumerate(wavs):\n            w = resample_poly(w, 3, 2).astype(np.float32)             # CLAP wants 48 kHz\n            for s in range(0, max(len(w) - W // 10, 1), W):           # drop tails < 1 s\n                chunks.append(w[s : s + W]); owner.append(b)\n        x = self.proc.feature_extractor(chunks, sampling_rate=48000, return_tensors="pt").to(self.dev)\n        a = self._feat(self.model.get_audio_features(**x))\n        a = a / a.norm(dim=-1, keepdim=True)\n        owner = torch.tensor(owner, device=self.dev)\n        clip = torch.stack([a[owner == b].mean(0) for b in range(len(wavs))])\n        return {"clap": ((clip / clip.norm(dim=-1, keepdim=True)) @ t.T)[:, 0].float().cpu().numpy()}\n\n\nclass Audiobox:\n    """Audiobox Aesthetics: resamples to 16 kHz and averages 10 s windows internally."""\n    AXES = ("CE", "CU", "PC", "PQ")\n\n    def __init__(self, device=None):\n        from audiobox_aesthetics.infer import initialize_predictor\n        self.pred = initialize_predictor()\n\n    def __call__(self, wavs, prompt=None):  # prompt-free by design\n        out = self.pred.forward([{"path": torch.from_numpy(w)[None], "sample_rate": SR} for w in wavs])\n        return {f"aes_{k}": np.array([o[k] for o in out], dtype=np.float32) for k in self.AXES}\n\n\nclass CmiRm:\n    """CMI-RM from a clone of CMI-RewardBench (repo_dir) + weights from HaiwenXia/CMI-RM.\n    T4 has no native bf16, so bf16=False."""\n    def __init__(self, repo_dir, checkpoint, device="cuda:0"):\n        sys.path.insert(0, f"{repo_dir}/baselines")\n        from inference import RewardModelInference\n        self.m = RewardModelInference(checkpoint=checkpoint, device=device, bf16=False)\n        self.sr = self.m.sr if hasattr(self.m, "sr") else 24000\n\n    def __call__(self, wavs, prompt):\n        import torchaudio\n        x = torchaudio.functional.resample(torch.from_numpy(np.stack(wavs)), SR, self.sr)\n        out = self.m.score_batch([{"audio": w[None], "text": prompt} for w in x], max_dur=30.0)\n        out = np.asarray(out, dtype=np.float32)\n        return {"cmi_ali": out[:, 0], "cmi_qual": out[:, 1]}\n\n\nclass MuqMulan:\n    """MuQ-MuLan (OpenMuQ/MuQ-MuLan-large): 24 kHz; clips longer than 10 s are cut into 10 s\n    pieces and their latents averaged by the model itself. Score = audio-text dot product."""\n    def __init__(self, device="cuda:0", name="OpenMuQ/MuQ-MuLan-large"):\n        from muq import MuQMuLan\n        self.dev = device\n        self.m = MuQMuLan.from_pretrained(name).to(device).eval()\n\n    @torch.inference_mode()\n    def __call__(self, wavs, prompt):\n        import torchaudio\n        x = torchaudio.functional.resample(torch.from_numpy(np.stack(wavs)), SR, self.m.sr).to(self.dev)\n        a = self.m(wavs=x)\n        t = self.m(texts=[prompt])\n        return {"mulan": self.m.calc_similarity(a, t)[:, 0].float().cpu().numpy()}\n', 'torch/score_judge.py': '"""\nScore the saved final WAVs of a corpus with one judge (second pass, no regeneration).\n\n  python torch/score_judge.py score --judge mulan --corpus data/corpus --wavs wavs --out mulan.json\n  python torch/score_judge.py score --judge cmi --repo CMI-RewardBench --ckpt .../model.safetensors ...\n  python torch/score_judge.py merge results/judge_mulan.json --corpus data/corpus\n\nBoth judges build MuQ\'s Wav2Vec2Conformer, which transformers 5.x rejects, so scoring runs in an\nenvironment with transformers 4.57 (see kaggle_judge/run.py). `score` writes {id: {key: [n]}}\n(resumable: the file is rewritten after every prompt); `merge` copies those keys into\n<corpus>/<id>.json["scores"] so frontier.py / selection.py read every judge the same way.\n"""\nimport argparse, json, os\nfrom pathlib import Path\nimport numpy as np\n\n\ndef atomic_write(path, obj):\n    tmp = Path(str(path) + ".tmp")\n    tmp.write_text(json.dumps(obj, indent=1))\n    os.replace(tmp, path)\n\n\ndef score(a):\n    from scipy.io import wavfile\n    from scorers import CmiRm, MuqMulan\n    m = MuqMulan(a.device) if a.judge == "mulan" else CmiRm(a.repo, a.ckpt, a.device)\n    out = Path(a.out)\n    done = json.loads(out.read_text()) if out.exists() else {}\n    for p in sorted(Path(a.corpus).glob("*.json")):\n        rec = json.loads(p.read_text())\n        if rec["id"] in done:\n            continue\n        wavs = [wavfile.read(Path(a.wavs) / f"{rec[\'id\']}_{r}.wav")[1].astype(np.float32) / 32767\n                for r in range(rec["n"])]\n        done[rec["id"]] = {k: v.tolist() for k, v in m(wavs, rec["prompt"]).items()}\n        atomic_write(out, done)\n        print(rec["id"], {k: np.round(v, 3).tolist() for k, v in done[rec["id"]].items()}, flush=True)\n\n\ndef merge(a):\n    scores = json.loads(Path(a.scores).read_text())\n    for pid, s in scores.items():\n        p = Path(a.corpus) / f"{pid}.json"\n        rec = json.loads(p.read_text())\n        rec["scores"].update(s)\n        atomic_write(p, rec)\n    print(f"merged {sorted({k for s in scores.values() for k in s})} into {len(scores)} prompts")\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    sub = ap.add_subparsers(dest="cmd", required=True)\n    s = sub.add_parser("score")\n    s.add_argument("--judge", choices=("mulan", "cmi"), required=True)\n    s.add_argument("--corpus", required=True)\n    s.add_argument("--wavs", required=True)\n    s.add_argument("--out", required=True)\n    s.add_argument("--device", default="cuda:0")\n    s.add_argument("--repo", default="CMI-RewardBench")\n    s.add_argument("--ckpt", default="CMI-RewardBench/baselines/model/model.safetensors")\n    m = sub.add_parser("merge")\n    m.add_argument("scores")\n    m.add_argument("--corpus", required=True)\n    a = ap.parse_args()\n    score(a) if a.cmd == "score" else merge(a)\n\n\nif __name__ == "__main__":\n    main()\n'}

if __name__ == "__main__":
    main()
